// listener: chạy MỖI scroll event
void _onScroll() {
  final p = _controller.position;
  if (p.pixels >
      p.maxScrollExtent - 200) {
    _loadMore();
  }
}
Future<void> _loadMore() async {
  if (_loading) return; // guard
  _loading = true; // cờ TRƯỚC await
  final page = await fetchPage(_page+1);
  _append(page); _loading = false;
}
